import { useEffect, useRef } from 'react';
import { SelectOption } from './types';

type ScrollIntoViewProps<T> = {
  options: SelectOption<T>[];
  selectedOption?: SelectOption<T>;
  tempSelectedOption?: SelectOption<T>;
  shouldShowConfirmButton?: boolean;
};

export const useScrollIntoView = <T>({
  options,
  selectedOption,
  tempSelectedOption,
  shouldShowConfirmButton,
}: ScrollIntoViewProps<T>) => {
  const refs = useRef<(HTMLElement | null)[]>([]);

  useEffect(() => {
    const currentOption = shouldShowConfirmButton ? tempSelectedOption : selectedOption;
    if (!currentOption) return;

    const selectedIndex = options.findIndex(
      (option) => option.value === currentOption.value && option.label === currentOption.label,
    );

    if (selectedIndex === -1) return;

    // 해당 요소를 뷰포트 내로 스크롤합니다
    const element = refs.current[selectedIndex];
    if (element) {
      element.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    }
  }, [options, selectedOption, tempSelectedOption, shouldShowConfirmButton]);

  return { refs };
};
