type ConfirmButtonProps = {
  confirmButtonLabel: string;
  onConfirm: (event: React.MouseEvent<HTMLButtonElement>) => void;
};

export const ConfirmButton = ({ confirmButtonLabel, onConfirm }: ConfirmButtonProps) => {
  return (
    <div className="bottom-sheet-footer">
      <button type="button" className="btn-sheet-confirm" onClick={onConfirm}>
        {confirmButtonLabel}
      </button>
    </div>
  );
};
